var u=[{id:"vaser4d",num:1,cat:"contour",trackPref:"contour",titleAr:"نحت القوام الديناميكي بالفيزر 4D",titleEn:"4D VASER High-Definition Liposuction",layers:["الدهون","تحفيز الجلد"],desc:"تقنية موجات فوق صوتية انتقائية تذيب الدهون الموضعية العنيدة بدقة عالية مع الحفاظ على الأوعية الدموية والأنسجة الضامة، مما يبرز تفاصيل الخصر أو خطوط العضلات الرياضية مع تحفيز انكماش الجلد.",scar:"فتحات دقيقة جداً (3 – 4 مم) مخفية داخل الثنيات الطبيعية وخط الملابس الداخلية وتتلاشى تدريجياً.",ideal:"أوزان متقاربة من المثالي (BMI < 30–32) مع دهون موضعية عنيدة وجلد يتمتع بمرونة جيدة.",notEnough:"لا يكفي وحده عند وجود تدلٍ واضح بالجلد (Apron) أو انفصال متوسط إلى شديد في عضلات البطن (حيث يزداد الترهل إذا لم يُزل الجلد الزائد).",anesthesia:"تخدير كلي أو نصفي حسب المناطق",hospital:"خروج في نفس اليوم أو ليلة واحدة",recovery:"العمل المكتبي 5 – 7 أيام • الكارديو 2 – 3 أسابيع • الجيم 4 – 6 أسابيع",cmp:{layers:"طبقة الدهون العميقة والسطحية + تحفيز انكماش الجلد",muscle:"لا يُصلح انفصال العضلات",scar:"فتحات مجهرية (3–4 مم) غير ظاهرة",anesthesia:"تخدير كلي أو نصفي",recovery:"5 – 7 أيام للعمل المكتبي",garment:"6 أسابيع (مع مساج ليمفاوي)",longevity:"دائمة مع ثبات الوزن ونمط الحياة",keyDiff:"الخيار الذهبي لتحديد المنحنيات والخصر عندما يكون الجلد مشدوداً."}},{id:"full_abdominoplasty",num:2,cat:"abdomen_mommy",trackPref:"mommy",titleAr:"شد البطن الكلي وإصلاح انفصال العضلات",titleEn:"Full Abdominoplasty + Muscle Plication",layers:["الجلد","العضلات","الدهون"],desc:'إعادة بناء كاملة لجدار البطن تشمل إزالة كامل الجلد المترهل أعلى وأسفل السرة، تقريب وإصلاح انفصال العضلات المستقيمة (Diastasis) كـ"مشد داخلي دائم"، وإعادة تشكيل السرة، وغالباً يُدمج مع نحت الخصر بالفيزر.',scar:"خط جراحي عرضي منخفض جداً مخفي تماماً أسفل خط الملابس الداخلية، مع أثر دائري دقيق داخل السرة.",ideal:"ترهل البطن الواضح بعد الولادات المتكررة أو فقدان الوزن، أو وجود انفصال عضلي واضح (أكثر من 2.5–3 سم).",notEnough:"إذا كان هناك ترهل دائري شديد يمتد للظهر والمؤخرة بعد التكميم فقد يلزم الشد الحزامي 360°.",anesthesia:"تخدير كلي",hospital:"ليلة واحدة إلى ليلتين للملاحظة الطبية",recovery:"العمل المكتبي 10 – 14 يوماً • الكارديو 4 – 6 أسابيع • تمارين البطن 8 – 12 أسبوعاً",cmp:{layers:"الجلد الزائد + العضلات (Diastasis) + نحت الخصر",muscle:"إصلاح كامل لانفصال العضلات من أعلى لأسفل البطن",scar:"خط منخفض مخفي أسفل الملابس الداخلية + حول السرة",anesthesia:"تخدير كلي",recovery:"10 – 14 يوماً للعمل المكتبي",garment:"6 – 8 أسابيع",longevity:"طويلة الأمد جداً (تتأثر فقط بحمل لاحق أو تغير وزن كبير)",keyDiff:"الحل الجذري الوحيد للجلد المترهل وإصلاح انفصال العضلات معاً."}},{id:"mini_abdominoplasty",num:3,cat:"abdomen_mommy",trackPref:"mommy",titleAr:"شد البطن المصغّر",titleEn:"Mini Abdominoplasty",layers:["الجلد السفلي","الدهون"],desc:"إزالة فائض الجلد المحدود في الجزء السفلي أسفل السرة فقط دون تغيير موضع السرة، وغالباً يُدمج مع شفط ونحت أعلى البطن والخصر بالفيزر.",scar:"خط قصير ومنخفض جداً شبيه بموضع ندبة الولادة القيصرية بدون أي جرح حول السرة.",ideal:"مرضى لديهم ترهل خفيف إلى متوسط محصور تماماً أسفل السرة مع تماسك ممتاز في جلد أعلى البطن.",notEnough:"لا يعالج الترهل فوق السرة ولا يُصلح الانفصال العضلي الممتد لأعلى البطن؛ اختياره في غير موضعه يعطي نتيجة غير مكتملة.",anesthesia:"تخدير كلي أو نصفي",hospital:"خروج نفس اليوم أو ليلة واحدة",recovery:"العمل المكتبي 7 – 10 أيام • الكارديو 3 – 4 أسابيع • الجيم 6 – 8 أسابيع",cmp:{layers:"الجلد أسفل السرة فقط + نحت دهون الخصر",muscle:"إصلاح محدود أسفل السرة فقط عند الحاجة",scar:"خط قصير منخفض بدون جرح حول السرة",anesthesia:"تخدير كلي أو نصفي",recovery:"7 – 10 أيام",garment:"6 أسابيع",longevity:"مستقرة مع ثبات الوزن",keyDiff:"ندبة أقصر وتعافٍ أسرع لكنه مخصص فقط لترهل أسفل السرة."}},{id:"belt_360",num:4,cat:"postweight",trackPref:"bariatric",titleAr:"الشد الحزامي الكامل 360°",titleEn:"Lower Body Lift / Belt Lipectomy 360°",layers:["الجلد 360°","العضلات","الدهون"],desc:"إجراء متكامل يشد محيط الجسم بالكامل (البطن، الخصر، أسفل الظهر، وجانبي الفخذين) في خطوة واحدة، مع رفع طبيعي للمؤخرة المترهلة بعد فقدان الوزن الكبير.",scar:"خط دائري منخفض يلتف حول محيط الحوض بحيث يظل مخفياً أسفل خط الملابس الداخلية.",ideal:"بعد فقدان وزن كبير (> 25 – 30 كجم) أو تكميم معدة مع ترهل واضح في البطن وأسفل الظهر والمؤخرة معاً.",notEnough:"يتطلب ثبات الوزن 6 أشهر على الأقل ومخزون هيموجلوبين وبروتين ممتاز قبل الجراحة.",anesthesia:"تخدير كلي",hospital:"ليلتان بالمستشفى للرعاية والمتابعة الدقيقة",recovery:"العمل المكتبي 2 – 3 أسابيع • الكارديو 6 أسابيع • الجيم الكامل 10 – 12 أسبوعاً",cmp:{layers:"الجلد الدائري 360° + عضلات البطن + رفع المؤخرة",muscle:"إصلاح كامل لعضلات البطن الأمامية",scar:"خط حزامي دائري منخفض أسفل الملابس الداخلية",anesthesia:"تخدير كلي",recovery:"2 – 3 أسابيع للعمل المكتبي",garment:"8 أسابيع",longevity:"جذرية ومستدامة مع ثبات الوزن",keyDiff:"يعالج ترهل الظهر والمؤخرة مع البطن بدلاً من شد الأمام فقط."}},{id:"fleur_de_lis",num:5,cat:"postweight",trackPref:"bariatric",titleAr:"شد البطن الطولي والعرضي (Fleur-de-Lis)",titleEn:"Fleur-de-Lis Abdominoplasty",layers:["الجلد الطولي والعرضي","العضلات"],desc:"تقنية متخصصة لإزالة فائض الجلد الشديد في الاتجاهين الرأسي والأفقي معاً، مما يمنح تضييقاً درامياً للخصر وإزالة طيات أعلى البطن التي لا يزيلها الشد العرضي وحده.",scar:"ندبة عرضية منخفضة بالإضافة إلى خط طولي رفيع بمنتصف البطن (تُناقش شفافيتها قبل القرار).",ideal:"حالات ما بعد فقدان الوزن الضخم (> 35–40 كجم) مع طيات جلدية كثيفة في أعلى ومنتصف البطن.",notEnough:"لا يُلجأ إليه في الترهل العادي؛ هو مخصص فقط لمن يمثل فائض الجلد العرضي لديهم مشكلة حقيقية تستحق الخط الطولي.",anesthesia:"تخدير كلي",hospital:"ليلتان بالمستشفى",recovery:"العمل المكتبي 2 – 3 أسابيع • الجيم الكامل 10 – 12 أسبوعاً",cmp:{layers:"إزالة فائض الجلد في بعدين (رأسي + أفقي) + العضلات",muscle:"إصلاح كامل لانفصال العضلات",scar:"خط منخفض + خط طولي رفيع بمنتصف البطن",anesthesia:"تخدير كلي",recovery:"2 – 3 أسابيع",garment:"6 – 8 أسابيع",longevity:"جذرية ومستقرة",keyDiff:"يُزيل ترهل وطيات أعلى البطن العرضية التي يعجز عنها الشد التقليدي."}},{id:"mommy_makeover",num:6,cat:"abdomen_mommy",trackPref:"mommy",titleAr:"باقة ما بعد الولادة المتكاملة (Mommy Makeover)",titleEn:"Comprehensive Mommy Makeover",layers:["الجلد","العضلات","الدهون","الثدي"],desc:"خطة مصممة فردياً لكل أم تجمع غالباً بين شد البطن وإصلاح انفصال العضلات ونحت الخصر مع رفع أو تنسيق الثدي، سواء في جلسة واحدة آمنة أو على مرحلتين حسب مدة الجراحة والتحاليل.",scar:"خط شد بطن منخفض مخفي، مع ندبات رفع الثدي الدقيقة المخفية حول الهالة والثنية السفلية.",ideal:"الأمهات بعد إتمام خطة الإنجاب (أو بعد 6–9 شهور من الولادة و6 شهور من انتهاء الرضاعة).",notEnough:"لا يُنصح بدمج أكثر من إجراء في جلسة واحدة إذا تجاوزت المدة الآمنة للتخدير أو كان الهيموجلوبين منخفضاً؛ التقسيم على مرحلتين حينها أكثر أماناً.",anesthesia:"تخدير كلي",hospital:"ليلة إلى ليلتين",recovery:"العمل المكتبي 2 أسبوع • الجيم الكامل 8 – 12 أسبوعاً",cmp:{layers:"إعادة هندسة شاملة للبطن والخصر والثدي معاً",muscle:"إصلاح كامل لعضلات البطن (Diastasis)",scar:"خط شد البطن المنخفض + خطوط رفع الثدي المخفية",anesthesia:"تخدير كلي",recovery:"14 – 21 يوماً",garment:"6 – 8 أسابيع (مشد بطن + حمالة طبية)",longevity:"طويلة الأمد بعد اكتمال خطة الأسرة",keyDiff:"يجمع تعافياً واحداً لإصلاح تغيرات الحمل بالبطن والصدر معاً."}},{id:"fat_grafting",num:7,cat:"contour",trackPref:"contour",titleAr:"حقن الدهون الذاتية المغلق الموجه بالسونار",titleEn:"MicroAire & LipoSurge Ultrasound-Guided Fat Grafting",layers:["الدهون الذاتية","إعادة التوزيع"],desc:"شفط ونحت دقيق للدهون بنظام مغلق معقّم (MicroAire / LipoSurge) يحافظ على حيوية الخلايا الدهنية دون تعرض للهواء، ثم حقنها تحت التوجيه الآمن بالسونار (Ultrasound-Guided) في الطبقة السطحية الآمنة فقط لتناسق الوركين والمؤخرة أو الثدي.",scar:"فتحات دقيقة جداً (3 – 4 مم) بدون أي ندبات جراحية طويلة.",ideal:"الراغبات في امتلاء طبيعي 100% من أنسجة الجسم مع نحت متزامن للخصر والظهر وتوفر مخزون دهني مناسب.",notEnough:"لا يصلح لشد الترهل الجلدي الشديد، ولا يناسب النحافة الشديدة (BMI < 18.5) لعدم توفر دهون كافية.",anesthesia:"تخدير كلي",hospital:"خروج نفس اليوم أو ليلة واحدة",recovery:"منع الضغط المباشر 3 – 4 أسابيع (استخدام وسادة مخصصة) • الجيم 6 – 8 أسابيع",cmp:{layers:"نقل وإعادة توزيع الخلايا الدهنية الذاتية بالطبقة الآمنة",muscle:"لا يتدخل في العضلات (الحقن فوق العضلة بالسونار للأمان)",scar:"فتحات إبرية دقيقة فقط",anesthesia:"تخدير كلي",recovery:"7 – 14 يوماً (مع تجنب الضغط المباشر 3–4 أسابيع)",garment:"6 أسابيع (مشد مفرّغ فوق منطقة الحقن)",longevity:"الخلايا المستقرة (60–75%) تبقى دائمة وتتأثر بالوزن",keyDiff:"امتلاء طبيعي من أنسجتك الذاتية + نحت متزامن للخصر بدون أجسام غريبة."}},{id:"brachioplasty",num:8,cat:"postweight",trackPref:"bariatric",titleAr:"شد وتجميل الذراعين",titleEn:"Brachioplasty (Arm Lift)",layers:["الجلد","الدهون"],desc:"إزالة الجلد المترهل والدهون المتدلية أسفل الذراعين لإعادة محيط ذراع مشدود ومتناسق، وغالباً يسبقه نحت مساعد بالفيزر لتقليل التورم والحفاظ على الأوعية الليمفاوية.",scar:"خط جراحي دقيق موضوع بعناية في الجانب الداخلي للذراع بحيث يكون غير ظاهر عند النظر من الأمام أو الخلف.",ideal:"ترهل الذراعين المتوسط إلى الشديد بعد التكميم أو فقدان الوزن الكبير.",notEnough:"في الترهل الطفيف جداً مع جلد مرن نكتفي بالفيزر والشد المساعد دون الحاجة لندبة شد الذراعين.",anesthesia:"تخدير كلي",hospital:"خروج نفس اليوم أو ليلة واحدة",recovery:"العمل المكتبي 10 – 14 يوماً • الجيم وأوزان الذراعين 6 – 8 أسابيع",cmp:{layers:"إزالة فائض الجلد + نحت دهون الذراع",muscle:"لا يمس العضلات",scar:"خط رفيع بالجانب الداخلي للذراع (يخف تدريجياً بالسيليكون)",anesthesia:"تخدير كلي",recovery:"10 – 14 يوماً",garment:"6 أسابيع (مشد ذراعين طبي)",longevity:"مستقرة وطويلة الأمد",keyDiff:"الحل الحقيقي للجلد المتدلي بالذراعين حيث لا يكفي الشفط."}},{id:"thigh_lift",num:9,cat:"postweight",trackPref:"bariatric",titleAr:"شد وتجميل الفخذين",titleEn:"Medial / Extended Thigh Lift",layers:["الجلد","الدهون"],desc:"شد ترهل الجزء الداخلي للفخذين وإزالة الاحتكاك الجلدي المزعج أثناء المشي بعد نزول الوزن، مع نحت متوازن للدهون المحيطة.",scar:"مخفية داخل ثنية الفخذ العلوية (للترهل المتوسط) أو تمتد طولياً بالجانب الداخلي للفخذ في حالات ما بعد التكميم الشديد.",ideal:"الترهل الجلدي الواضح والاحتكاك بالجزء الداخلي للفخذين بعد فقدان وزن كبير.",notEnough:"يتطلب عناية دقيقة بجفاف الثنيات وراحة من الخطوات الواسعة أول أسبوعين لحماية خط الخياطة.",anesthesia:"تخدير كلي",hospital:"ليلة واحدة بالمستشفى",recovery:"العمل المكتبي 2 أسبوع • الكارديو 5 أسابيع • الجيم 6 – 8 أسابيع",cmp:{layers:"إزالة الجلد الزائد + نحت دهون الفخذ الداخلي",muscle:"لا يمس العضلات",scar:"ثنية الفخذ العلوية أو خط داخلي حسب درجة الترهل",anesthesia:"تخدير كلي",recovery:"10 – 14 يوماً",garment:"6 أسابيع (شورت طبي ضاغط)",longevity:"دائمة مع استقرار الوزن",keyDiff:"يزيل الجلد المترهل والاحتكاك الداخلي ويشد محيط الفخذ."}},{id:"mastopexy",num:10,cat:"chest_men",trackPref:"mommy",titleAr:"رفع وشد الثدي",titleEn:"Mastopexy (Breast Lift)",layers:["الجلد","أنسجة الثدي"],desc:"إعادة تشكيل أنسجة الثدي ورفع الحلمة لموضعها التشريحي الشاب وإزالة الجلد المترهل بعد الحمل والرضاعة أو التخسيس، ويمكن دمجه بحشوة أو دهون ذاتية عند الرغبة في امتلاء علوي إضافي.",scar:"حول الهالة وخط عمودي رفيع (Lollipop) أو مع خط مخفي داخل الثنية السفلية (Anchor) حسب درجة التهدل.",ideal:"هبوط الحلمة وترهل جلد الثدي بعد الرضاعة أو نزول الوزن.",notEnough:"لا يُجرى أثناء الرضاعة؛ يُنصح بالانتظار 6 أشهر بعد الفطام التام لاستقرار حجم وأنسجة الثدي.",anesthesia:"تخدير كلي",hospital:"خروج نفس اليوم أو ليلة واحدة",recovery:"العمل المكتبي 7 – 10 أيام • حمالة طبية 6 أسابيع • الجيم 6 أسابيع",cmp:{layers:"إزالة الجلد الزائد وإعادة تشكيل ورفع نسيج الثدي",muscle:"لا يمس العضلات",scar:"حول الهالة وخط طولي/ثنية سفلية مخفية",anesthesia:"تخدير كلي",recovery:"7 – 10 أيام",garment:"6 أسابيع (حمالة طبية داعمة)",longevity:"طويلة الأمد (تتأثر بتغيرات الوزن أو الحمل)",keyDiff:"يرفع الحلمة ويشد التهدل بدلاً من تكبير ثدي مترهل بحشوة فقط."}},{id:"breast_reduction",num:11,cat:"chest_men",trackPref:"mommy",titleAr:"تصغير الثدي الطبي والتجميلي",titleEn:"Reduction Mammaplasty",layers:["النسيج الغدي والدهني","الجلد"],desc:"إزالة الوزن الزائد من أنسجة الثدي ورفعه بتناسق أنثوي مريح لتخفيف آلام الرقبة والظهر والكتفين وعلامات حمالة الصدر والالتهابات أسفل الثدي.",scar:"حول الهالة وخط عمودي وثنية سفلية مخفية تبهت تدريجياً مع العناية بالسيليكون.",ideal:"تضخم الثدي المصحوب بألم مزمن بالرقبة والظهر أو صعوبة في الرياضة والملابس.",notEnough:"إجراء علاجي وتجميلي عالي الرضا، ويتطلب تقييماً دقيقاً للتحاليل وفحص الثدي قبل الجراحة.",anesthesia:"تخدير كلي",hospital:"ليلة واحدة بالمستشفى",recovery:"العمل المكتبي 10 – 14 يوماً • الجيم 6 أسابيع",cmp:{layers:"تصغير الوزن والحجم + شد الجلد ورفع الحلمة",muscle:"لا يمس العضلات (يريح عضلات الظهر والرقبة)",scar:"حول الهالة وخط عمودي وثنية سفلية مخفية",anesthesia:"تخدير كلي",recovery:"10 – 14 يوماً",garment:"6 أسابيع (حمالة طبية)",longevity:"دائمة ومستقرة مع ثبات الوزن",keyDiff:"يجمع بين الراحة الطبية لآلام الظهر والشد التجميلي المتناسق."}},{id:"gynecomastia",num:12,cat:"chest_men",trackPref:"men",titleAr:"علاج التثدي ونحت الصدر للرجال",titleEn:"Gynecomastia 4D Surgery",layers:["الغدة الليفية","الدهون","الجلد"],desc:"إزالة الدهون ونحت حدود عضلة الصدر بالفيزر 4D مع استئصال الغدة الليفية الصلبة عبر فتحة مجهرية أسفل حافة الهالة لضمان صدر ذكوري مسطح ومحدد، مع شد الجلد في الدرجات المتقدمة.",scar:"شق مجهرى دقيق جداً على حافة الهالة السفلية يكاد يختفي تماماً (أو خطوط شد في الدرجة 4 الشديدة).",ideal:"الرجال الذين يعانون من بروز الصدر (الدرجات 1 إلى 4) سواء دهني أو غدي أو بعد نزول وزن كبير.",notEnough:"الشفط وحده دون إزالة الغدة الليفية يترك بروزاً خلف الحلمة؛ الدمج بين الفيزر واستئصال الغدة هو المعيار القياسي.",anesthesia:"تخدير كلي أو موضعي مع مهدئ",hospital:"خروج في نفس اليوم",recovery:"العمل المكتبي 3 – 5 أيام • الكارديو 2 أسبوع • تمارين الصدر 4 – 6 أسابيع",cmp:{layers:"دهون الصدر + استئصال الغدة الليفية (+ شد جلد للدرجة 4)",muscle:"يُبرز حدود عضلة الصدر دون المساس بها",scar:"شق دقيق أسفل حافة الهالة يكاد لا يُرى",anesthesia:"تخدير كلي أو موضعي مع مهدئ",recovery:"3 – 5 أيام للعمل المكتبي",garment:"4 – 6 أسابيع (مشد صدر طبي)",longevity:"دائمة تماماً (الغدة المستأصلة لا تعود)",keyDiff:"يزيل الغدة الليفية الصلبة مع نحت دهون الصدر بفتحة مخفية."}},{id:"energy_tightening",num:13,cat:"contour",trackPref:"contour",titleAr:"تقنيات الشد المساعد للجلد مع النحت",titleEn:"Energy-Assisted Skin Tightening (J-Plasma / RF / Endolift)",layers:["ألياف الكولاجين تحت الجلد"],desc:"توجيه طاقة حرارية محكومة تحت الجلد مباشرة عقب النحت بالفيزر لتقليص الحواجز الليفية وتحفيز انكماش إضافي للجلد في حالات الارتخاء الخفيف إلى المتوسط الحدي.",scar:"يُستخدم عبر نفس فتحات الفيزر الدقيقة (3 – 4 مم) دون أي جروح إضافية.",ideal:"حالات الترهل الخفيف إلى المتوسط المبكر بالبطن أو الذراعين أو الفخذين لمن لا يحتاجون قص جلد.",notEnough:"حقيقة طبية صادقة: لا يستطيع أي جهاز طاقة إزالة الجلد المتدلي الشديد أو استبدال شد البطن الجراحي في الترهل المتقدم.",anesthesia:"تُدمج مع تخدير عملية الفيزر",hospital:"نفس إقامة النحت (خروج نفس اليوم)",recovery:"نفس تعافي الفيزر (5 – 7 أيام عمل • 6 أسابيع مشد)",cmp:{layers:"الحواجز الليفية والكولاجين تحت الجلد",muscle:"لا يُصلح انفصال العضلات",scar:"بدون أي جروح إضافية (نفس فتحات الفيزر)",anesthesia:"مدمجة مع تخدير النحت",recovery:"5 – 7 أيام",garment:"6 أسابيع",longevity:"انكماش تدريجي يكتمل خلال 3 – 6 أشهر",keyDiff:"يرفع نسبة انكماش الجلد في الترهل البسيط لكنه لا يغني عن القص في الترهل الشديد."}},{id:"lipedema",num:14,cat:"contour",trackPref:"contour",titleAr:"الجراحة التخصصية للوذمة الدهنية (Lipedema)",titleEn:"Lymph-Sparing Lipedema Specialized Liposuction",layers:["الدهون المرضية المتليفة","حماية الأوعية الليمفاوية"],desc:"بروتوكول جراحي متخصص ومختلف عن الشفط التجميلي التقليدي، يستخدم تقنيات لطيفة موازية لمسار الأوعية الليمفاوية لإزالة الدهون المرضية المؤلمة والمتراكمة بشكل متماثل في الساقين أو الذراعين لتخفيف الألم وتحسين الحركة.",scar:"فتحات دقيقة وموزعة بعناية لحماية المسارات الليمفاوية.",ideal:"السيدات المصابات بسمنة متماثلة ومؤلمة بالساقين أو الذراعين (مع كدمات تلقائية ومقاومة تامة للدايت والرياضة، بينما تظل القدم واليد سليمتين).",notEnough:"الدايت القاسي لا يزيل دهون الوذمة الدهنية؛ بل تتطلب تشخيصاً دقيقاً وعلاجاً جراحياً محافظاً على الليمفاويات مع مشدات طبية مخصصة (Flat-Knit).",anesthesia:"تخدير كلي أو نصفي (وقد تُقسم على مراحل آمنة)",hospital:"ليلة واحدة للمتابعة",recovery:"العمل 10 – 14 يوماً • مشد طبي خاص 6 – 8 أسابيع • مساج ليمفاوي متخصص",cmp:{layers:"الدهون المرضية مع حماية صارمة للأوعية الليمفاوية",muscle:"يحسن حركة وميكانيكية الساقين ويخفف العبء عن المفاصل",scar:"فتحات دقيقة مخفية",anesthesia:"تخدير كلي أو نصفي",recovery:"10 – 14 يوماً",garment:"6 – 8 أسابيع (مشد طبي ليمفاوي)",longevity:"تخفيف دائم للألم والحجم المرضي",keyDiff:"إجراء علاجي تخصصي لحالة طبية حقيقية وليس مجرد شفط تجميلي."}}],A=[{myth:"«أجهزة تفتيت وتجميد الدهون بتغني عن الفيزر»",fact:"الأجهزة الخارجية مثل الكرايو أو الكافيتيشن قد تعطي تقليلاً طفيفاً جداً في طبقة دهون سطحية محدودة على مدار جلسات كثيرة، لكنها لا تنحت تفاصيل القوام ولا تزيل التراكمات الدهنية المتوسطة أو العميقة ولا تحقق انكماش الجلد الذي يوفره الفيزر رباعي الأبعاد في جلسة واحدة."},{myth:"«الفيزر عملية تخسيس وإنقاص وزن»",fact:"الفيزر ليس أداة للتخسيس أو علاج السمنة المفرطة؛ هو أداة هندسية لنحت وتنسيق القوام وإزالة الدهون العنيدة التي لا تستجيب للدايت. القاعدة الطبية الآمنة هي تقليل الوزن أولاً عندما يكون مؤشر كتلة الجسم مرتفعاً (BMI ≥ 35) لضمان أعلى أمان للتخدير وأدق تحديد للخصر."},{myth:"«الدهون بترجع تاني في نفس المكان بعد الشفط»",fact:"الخلايا الدهنية التي تُزال بالشفط لا تتجدد ولا تعود مرة أخرى في نفس الموضع. لكن إذا زاد وزن الجسم بشكل كبير لاحقاً، تتمدد الخلايا الدهنية المتبقية في باقي مناطق الجسم؛ لذلك ثبات الوزن يحفظ نتيجتك لسنوات طويلة."},{myth:"«تمارين البطن والكورسيه بيقفلوا انفصال العضلات الشديد»",fact:"العلاج الطبيعي وتمارين الكور العميقة مفيدة جداً في الانفصال الخفيف (1.5 – 2 إصبع). أما في الانفصال المتوسط والشديد (أكثر من 2.5 – 3 أصابع أو مع فتق سري) فإن النسيج الليفي الوسطي (Linea Alba) يكون قد تمدد فعلياً؛ والكورسيه يضغط مؤقتاً فقط ولا يُغلق الفجوة، ويبقى الإصلاح الجراحي للعضلات هو الحل البنيوي الحقيقي."},{myth:"«أقدر أعمل شد بطن بعد شهرين من الولادة أو التكميم فوراً»",fact:"التسرع هنا يضر بالنتيجة والأمان. بعد الولادة يحتاج الرحم والأربطة والهرمونات 6 – 9 شهور للعودة لوضعها المستقر، وبعد التكميم يحتاج الجسم 12 – 18 شهراً مع 6 أشهر من ثبات الوزن وتعويض مخزون الحديد والبروتين حتى يلتئم الجرح بقوة ولا يرتخي الجلد مجدداً."},{myth:"«سمنة الساقين المؤلمة اللي مبتنزلش بالدايت هي مجرد سمنة عادية»",fact:"عندما تتراكم الدهون بشكل متماثل ومؤلم عند اللمس في الساقين أو الذراعين مع سهولة ظهور كدمات ومقاومة تامة للدايت (مع بقاء القدم واليد طبيعيتين)، فهذه غالباً حالة طبية تُسمى «الوذمة الدهنية - Lipedema» وليست سمنة عادية؛ وعلاجها يتطلب بروتوكولاً جراحياً تخصصياً محافظاً على الأوعية الليمفاوية."}];export{u as a,A as b};
